/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`sofie`@`localhost` FUNCTION `f_checkIDProfileByNumAppel`(
        _NumAppel VARCHAR(12)
    ) RETURNS tinyint(4)
    DETERMINISTIC
BEGIN

DECLARE IDPROFIL TINYINT(4);
DECLARE PROFIL_VALIDITY TINYINT(4);

SELECT IF(COUNT(*)>0,`t_numeroappel`.`IDProfile`,0) INTO IDPROFIL FROM `t_numeroappel` WHERE `t_numeroappel`.`NumAppel`=_NumAppel;

IF IDPROFIL = 1 THEN 

	SELECT IF(COUNT(*)>0,1,0) INTO PROFIL_VALIDITY FROM `t_comite` WHERE `t_comite`.`IDNumAppel`=f_getIDNumappelByNumAppel(_NumAppel) AND ISNULL(`t_comite`.`deleted_at`);

END IF;

IF IDPROFIL = 2 THEN -- Reparateur

	SELECT IF(COUNT(*)>0,1,0) INTO PROFIL_VALIDITY FROM `t_reparateur` WHERE `t_reparateur`.`IDNumAppel`=f_getIDNumappelByNumAppel(_NumAppel) AND ISNULL(`t_reparateur`.`deleted_at`);

END IF;

IF IDPROFIL >= 3 THEN

	SELECT IF(COUNT(*)>0,1,0) INTO PROFIL_VALIDITY FROM `t_agent` WHERE `t_agent`.`IDNumAppel`=f_getIDNumappelByNumAppel(_NumAppel) AND ISNULL(`t_agent`.`deleted_at`);

END IF;

IF PROFIL_VALIDITY > 0 THEN
	RETURN IDPROFIL;
ELSE

	RETURN 0;
    
END IF;
  
END ;;
DELIMITER ;
