CREATE DEFINER=`sofie`@`%` FUNCTION `f_generateTicket`() RETURNS varchar(5) CHARSET latin1
    DETERMINISTIC
BEGIN
DECLARE new_ticket VARCHAR(5);

  label1: LOOP
    
    SELECT FLOOR((RAND() * 10000 + 10000)) INTO new_ticket;
    

	IF `f_ifexist_num_panne`(new_ticket)>0 THEN
    	ITERATE label1;
	END IF;
    
    LEAVE label1;
    
  END LOOP label1;
  
  RETURN new_ticket;
  
END ;;
