CREATE DEFINER=`sofie`@`%` PROCEDURE `P_UPDATE_OUVRAGE_STATUS_BY_IDAGENT`( IN _OUVRAGE_STATUS TINYINT ( 4 ) , IN _IDAGENT INTEGER ( 4 ))
BEGIN
DECLARE EXIT HANDLER FOR SQLEXCEPTION ROLLBACK;
